net.ipv4.tcp_tw_reuse = 1
fs.file-max = 2097152`}],m8=({isOpen:e,onClose:t,initialFilePath:r="/etc/nginx/nginx.conf",initialContent:n="",onSaveToRemote:i})=>{const[a,o]=N.useState(r),[l,c]=N.useState(n||lf[0].content),[d,p]=N.useState(n||lf[0].content),[u,x]=N.useState("editor"),[b,y]=N.useState(!1),[v,g]=N.useState(!1);if(!e)return null;const f=S=>{o(S.path),c(S.content),p(S.content)},h=()=>{i&&i(a,d),y(!0),setTimeout(()=>y(!1),2500)},m=()=>{navigator.clipboard.writeText(d),g(!0),setTimeout(()=>g(!1),2e3)},_=l.split(`
